"Knife",rarity="Common",icon="http://www.roblox.com/Thumbs/Asset.ashx?format=png&width=250&height=250&assetId=11254145154",itemId="11254145154",year="2022",chroma=false,christmas=false,halloween=false,evo=false,source="module:ReplicatedStorage.Database.Sync.Item"},{key="ZombifiedK",name="Zombified",type="Knife",rarity="Uncommon",icon="http://www.roblox.com/Thumbs/Asset.ashx?format=png&width=250&height=250&assetId=4210928053",itemId="4210928053",year="2019",chroma=false,christmas=false,halloween=false,evo=false,source="module:ReplicatedStorage.Database.Sync.Item"},}local function loadCatalog()State.catalog={}State.byKey={}for _,raw in ipairs(MM2_NATIVE_SKINS)do if raw and(raw.type=="Knife"or raw.type=="Gun")then local item={key=raw.key,name=raw.name or raw.key,icon=raw.icon or"",type=raw.type,rarity=raw.rarity or"Common",itemId=raw.itemId,chroma=raw.chroma==true,christmas=raw.christmas==true,halloween=raw.halloween==true,evo=raw.evo==true,year=raw.year,source=raw.source,asset=nil,}table.insert(State.catalog,item)State.byKey[itemKey(item)]=item end end table.sort(State.catalog,function(a,b)if a.type~=b.type then return a.type=="Knife"end return lower(a.name)<lower(b.name)end)State.inventory={}for _,item in ipairs(State.catalog)do State.inventory[itemKey(item)]={item=item,amount=200}end end local function inventoryEntries(inv)local out={}for _,entry in pairs(inv or{})do if entry and entry.item and(entry.amount or 0)>0 then table.insert(out,entry)end end table.sort(out,function(a,b)return lower(a.item.name)<lower(b.item.name)end)return out end local function countOffer(offer,item)local n=0 for _,it in ipairs(offer or{})do if itemKey(it)==itemKey(item)then n=n+1 end end return n end local function addOffer(offer,inv,item)if#offer>=4 then return false,"Offer is full (4 items)."end local e=inv[itemKey(item)]if not e then return false,"Item not in inventory."end if(e.amount or 0)-countOffer(offer,item)<=0 then return false,"No copies left."end table.insert(offer,item)return true end local function removeInventory(inv,item,amount)amount=amount or 1 local e=inv[itemKey(item)]if not e or(e.amount or 0)<amount then return false end e.amount=e.amount-amount if e.amount<=0 then inv[itemKey(item)]=nil end return true end local function addInventory(inv,item,amount)amount=amount or 1 local k=itemKey(item)local e=inv[k]if not e then inv[k]={item=item,amount=amount}else e.amount=(e.amount or 0)+amount end end local function completeTrade()for _,item in ipairs(State.myOffer)do if not removeInventory(State.inventory,item,1)then return false,"Inventory changed before trade completed."end end for _,item in ipairs(State.botOffer)do addInventory(State.inventory,item,1)end State.myOffer={}State.botOffer={}State.meAccepted=false State.botAccepted=false return true end local function seedBotInventory()State.botInventory={}if#State.catalog==0 then return end local picks=math.min(20,#State.catalog)for i=1,picks do local item=State.catalog[math.random(1,#State.catalog)]State.botInventory[itemKey(item)]={item=item,amount=math.random(1,10)}end end local function buildBotOffer()State.botOffer={}local pool=inventoryEntries(State.botInventory)local n=math.min(#pool,math.random(1,3))for i=1,n do table.insert(State.botOffer,pool[i].item)end end local AssetCache={}local function scoreAsset(obj,item)if not obj then return-999999 end local score=0 if obj:IsA("Tool")then score=score+500 elseif obj:IsA("Accessory")then score=score+430 elseif obj:IsA("MeshPart")then score=score+350 elseif obj:IsA("Model")then score=score+280 elseif obj:IsA("BasePart")then score=score+180 else return-999999 end local n=lower(obj.Name)if n==lower(item.key)then score=score+220 end if n==lower(item.name)then score=score+190 end if contains(n,item.key)or contains(item.key,n)then score=score+50 end return score end local function findReplicatedAsset(item)local names={item.key,item.name}local roots={ReplicatedStorage,StarterPack}for _,root in ipairs(roots)do if root then for _,name in ipairs(names)do local ok,found=pcall(function()return root:FindFirstChild(name,true)end)if ok and found and scoreAsset(found,item)>-999 then return found end end end end return nil end local function loadItemAsset(item)if item.asset then return item.asset end local ck=tostring(item.itemId or item.key or item.name)if AssetCache[ck]then item.asset=AssetCache[ck]return item.asset end local localAsset=findReplicatedAsset(item)if localAsset then AssetCache[ck]=localAsset item.asset=localAsset return localAsset end return nil end local function prepPart(p)p.Anchored=false p.CanCollide=false p.CanTouch=false p.CanQuery=false p.Massless=true end local function makeTool(item)local srcAsset=loadItemAsset(item)if srcAsset and srcAsset:IsA("Tool")then local t=safeClone(srcAsset)if t then t.Name=item.name t.CanBeDropped=false t:SetAttribute("MM2V27",true)for _,p in ipairs(t:GetDescendants())do if p:IsA("BasePart")then prepPart(p)end end if t:FindFirstChild("Handle")then return t end t:Destroy()end end if srcAsset and srcAsset:IsA("Accessory")then local h=srcAsset:FindFirstChild("Handle")if h and h:IsA("BasePart")then local t=Instance.new("Tool")t.Name=item.name t.RequiresHandle=true t.CanBeDropped=false t:SetAttribute("MM2V27",true)local ch=h:Clone()ch.Name="Handle"prepPart(ch)ch.Parent=t t.Grip=item.type=="Gun"and(CFrame.new(0,-0.25,-0.55)*CFrame.Angles(0,math.rad(90),0))or CFrame.new(0,-0.45,-0.75)return t end end if srcAsset and srcAsset:IsA("BasePart")then local t=Instance.new("Tool")t.Name=item.name t.RequiresHandle=true t.CanBeDropped=false t:SetAttribute("MM2V27",true)local h=srcAsset:Clone()h.Name="Handle"prepPart(h)h.Parent=t t.Grip=item.type=="Gun"and(CFrame.new(0,-0.25,-0.55)*CFrame.Angles(0,math.rad(90),0))or CFrame.new(0,-0.45,-0.75)return t end local t=Instance.new("Tool")t.Name=item.name t.RequiresHandle=true t.CanBeDropped=false t:SetAttribute("MM2V27",true)local h=Instance.new("Part")h.Name="Handle"h.Material=Enum.Material.SmoothPlastic h.Size=item.type=="Gun"and Vector3.new(1.7,0.7,0.35)or Vector3.new(0.3,0.4,2.4)h.Color=item.type=="Gun"and Color3.fromRGB(70,70,78)or Color3.fromRGB(95,95,105)prepPart(h)h.Parent=t t.Grip=item.type=="Gun"and(CFrame.new(0,-0.25,-0.55)*CFrame.Angles(0,math.rad(90),0))or CFrame.new(0,-0.45,-0.75)return t end local function giveTool(item,equip)if not item then return false,"No weapon selected."end local tool=makeTool(item)if not tool then return false,"Could not create tool."end tool.Parent=Backpack if equip and LP.Character then local hum=LP.Character:FindFirstChildOfClass("Humanoid")if hum then hum:UnequipTools()task.wait()hum:EquipTool(tool)end end return true,item.name end local BotToken=0 local BotConnections={}local BotTracks={}local function botRoot(bot)return bot and(bot:FindFirstChild("HumanoidRootPart")or bot.PrimaryPart)end local function disconnectBotMotion()for _,con in ipairs(BotConnections)do pcall(function()con:Disconnect()end)end BotConnections={}for _,track in pairs(BotTracks)do pcall(function()track:Stop(0.12)end)end BotTracks={}end local function botBubble(bot,msg)if not bot or not bot.Parent then return end local head=bot:FindFirstChild("Head")or botRoot(bot)if not head then return end local text=tostring(msg or"")if text==""then return end local TextChatService=game:GetService("TextChatService")local ok=pcall(function()TextChatService:DisplayBubble(head,text)end)if ok then return end local old=bot:FindFirstChild("MM2V53_ChatFallback")if old then old:Destroy()end local bb=Instance.new("BillboardGui")bb.Name="MM2V53_ChatFallback"bb.Size=UDim2.fromOffset(92,58)bb.StudsOffset=Vector3.new(0,3.55,0)bb.AlwaysOnTop=true bb.MaxDistance=100 bb.LightInfluence=0 bb.Adornee=head bb.Parent=bot local bubble=Instance.new("Frame")bubble.Name="Bubble"bubble.AnchorPoint=Vector2.new(0.5,0)bubble.Position=UDim2.new(0.5,0,0,0)bubble.Size=UDim2.fromOffset(64,39)bubble.BackgroundColor3=Color3.fromRGB(250,250,250)bubble.BackgroundTransparency=0 bubble.BorderSizePixel=0 bubble.Parent=bb local corner=Insta